<script lang="ts">import {rows,text,numeric,priced,cost,stamp,number,percent,compact,type Row,type Query}from'../lib/api';import{tr}from'../lib/i18n';import Quota from './Quota.svelte';import Metrics from './Metrics.svelte';import Chart from './Chart.svelte';import Filters from './Filters.svelte';import Model from './Model.svelte';import DetailPopover from './DetailPopover.svelte';import {preview,metadata,duration} from './logFormat';export let data:Row={};export let query:Query;export let onchange:(q:Query)=>void;export let onerror:(e:any)=>void;export let onlogs:()=>void=()=>{};let share='tokens';$: models=rows(data.models);$: shareTotal=models.reduce((n,m)=>n+(Number(m[share])||0),0);let values:Row={};$: summary=data.summary??{};$: input=number(summary.input_tokens);$: read=number(summary.cached_input_tokens);$: write=number(summary.cache_write_input_tokens);$: output=number(summary.output_tokens);$: valid=input!==null&&read!==null&&write!==null&&output!==null&&read+write<=input;$: values={regular_input:valid?input!-read!-write!:null,cached_input_tokens:read,cache_write_input_tokens:write,output_tokens:output};$: parts=[['regular_input','普通输入','var(--input)'],['cached_input_tokens','缓存读取','var(--cache)'],['cache_write_input_tokens','缓存写入','var(--write)'],['output_tokens','输出','var(--output)']].filter(p=>p[0]!=='cache_write_input_tokens'||(write??0)>0);$: total=valid?input!+output!:0;</script>
<Quota quota={data.quota??{}}/><hr class="page-divider"/><div class="row between wrap"><h3 class="section-title">{tr('用量')}</h3><Filters {query} periodOnly {onchange}/></div><Metrics {summary} comparison={data.comparison??{}}/><Chart data={data.chart??[]}/>
<section class="surface overview-models"><div class="row between"><h3 class="section-title">{tr('模型贡献')}</h3><div class="segments" role="group" aria-label={tr('模型贡献')}>{#each [['tokens','Token'],['usd','费用'],['user_requests','用户请求']] as [key,label]}<button class:active={share===key} aria-pressed={share===key} onclick={()=>share=key}>{tr(label)}</button>{/each}</div></div>{#each models as m}<div class="model-share"><div class="row between"><span>{text(m.model)}</span><span>{share==='usd'?priced(m,'usd'):compact(m[share])} · {percent(shareTotal?Number(m[share])/shareTotal*100:null)}</span></div><div class="meter"><div style:width={`${shareTotal?(Number(m[share])||0)/shareTotal*100:0}%`} style:background="var(--tokens)"></div></div></div>{/each}{#if !models.length}<div class="empty small">{tr('暂无数据')}</div>{/if}<details class="overview-composition"><summary>{tr('Token 组成')}</summary><div class="token-bar">{#each parts as [key,label,color]}<span style:background={color} style:flex-grow={valid?(number(values[key])??0):0} title={`${tr(label)} ${numeric(values[key])}`}></span>{/each}</div><div class="token-legend">{#each parts as [key,label,color]}<span><i style:background={color}></i>{tr(label)} {valid&&total>0?((number(values[key])??0)/total*100).toFixed(1)+'%':'—'}</span>{/each}</div></details></section>
<div class="row recent-heading"><h3 class="section-title">{tr('最近请求')}</h3><button class="quiet muted" onclick={onlogs}>{tr('查看全部')}</button></div><section class="recent recent-table"><div class="recent-columns"><span>{tr('请求')}</span><span>{tr('模型')}</span><span>Token</span><span>{tr('费用')}</span><span>{tr('耗时')}</span><span>{tr('详情')}</span></div>{#each rows(data.recent).filter(r=>!['automatic_approval_review','context_compaction'].includes(r.record_kind)).slice(0,3) as r}<div class="recent-item"><div class="recent-prompt"><strong title={preview(r)}>{preview(r)}</strong><small title={metadata(r)}>{metadata(r,true)}</small></div><Model record={r}/><span>{compact(r.total_tokens)}</span><span title={priced(r)}>{cost(r.cost_usd??r.usd)}</span><span>{duration(r.duration_ms)}</span><DetailPopover id={String(r.id)} record={r} {onerror}/></div>{/each}{#if !rows(data.recent).length}<div class="empty small">{tr('暂无数据')}</div>{/if}</section>
